def faq_schema(items):
    return {"@type": "FAQPage", "mainEntity": [
        {"@type": "Question", "name": q, "acceptedAnswer": {"@type": "Answer", "text": a}}
        for q, a in items]}


def page(path, seo_title, description, body, *, schema_type="Article", faqs=None,
         noindex=False, og_image="assets/media/official-header.jpg", breadcrumbs=None,
         source_state="Official 1.0", video=None):
    depth = path.count("/")
    root = "../" * depth
    canonical = f"{DOMAIN}/{path}" if path else f"{DOMAIN}/"
    nav = "".join(f'<a href="{root}{href.lstrip("/")}">{label}</a>' for label, href in NAV)
    image_url = og_image if og_image.startswith("http") else f"{DOMAIN}/{og_image}"
    schemas = [{
        "@context": "https://schema.org", "@type": schema_type, "headline": seo_title,
        "name": seo_title, "description": description, "url": canonical, "image": image_url,
        "datePublished": "2026-08-29", "dateModified": UPDATED,
        "isPartOf": {"@type": "WebSite", "name": "Garden of Witches Wiki", "url": f"{DOMAIN}/"},
        "about": {"@type": "VideoGame", "name": "Garden of Witches", "gamePlatform": "PC"},
        "author": {"@type": "Organization", "name": "Garden of Witches Wiki Editorial Desk"},
        "publisher": {"@type": "Organization", "name": "Garden of Witches Wiki"},
    }]
    if path == "":
        schemas.append({"@context": "https://schema.org", "@type": "VideoGame", "name": "Garden of Witches", "operatingSystem": "Windows", "applicationCategory": "Game", "genre": ["Action roguelike", "RPG"], "author": {"@type": "Organization", "name": "Team Tapas"}})
    crumbs = breadcrumbs or ([('Home', '')] if path else [])
    if path:
        crumbs = [*crumbs, (seo_title, path)]
        schemas.append({"@context": "https://schema.org", "@type": "BreadcrumbList", "itemListElement": [
            {"@type": "ListItem", "position": i + 1, "name": label, "item": f"{DOMAIN}/{url}" if url else f"{DOMAIN}/"}
            for i, (label, url) in enumerate(crumbs)]})
    if video:
        schemas.append({"@context": "https://schema.org", "@type": "VideoObject", **video})
    if faqs:
        schemas.append({"@context": "https://schema.org", **faq_schema(faqs)})
    robots = '<meta name="robots" content="noindex,follow">' if noindex else '<meta name="robots" content="index,follow,max-image-preview:large">'
    full_title = seo_title
    breadcrumb_html = "" if not path else '<nav class="breadcrumbs" aria-label="Breadcrumb">' + ' <span>›</span> '.join(
        f'<a href="{root}{url}">{html.escape(label)}</a>' if url else f'<a href="{root}index.html">{html.escape(label)}</a>'
        for label, url in crumbs) + '</nav>'
    doc = f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{html.escape(full_title)}</title><meta name="description" content="{html.escape(description)}">{robots}
  <link rel="canonical" href="{canonical}"><meta property="og:title" content="{html.escape(full_title)}">
  <meta property="og:description" content="{html.escape(description)}"><meta property="og:type" content="article"><meta property="og:url" content="{canonical}">
  <meta property="og:image" content="{image_url}"><meta property="og:image:alt" content="Official Garden of Witches game media from Team Tapas">
  <meta name="twitter:card" content="summary_large_image"><meta name="theme-color" content="#15101e">
  <link rel="icon" href="{root}assets/mark.svg" type="image/svg+xml"><link rel="manifest" href="{root}site.webmanifest"><link rel="stylesheet" href="{root}assets/style.css">
  {''.join(f'<script type="application/ld+json">{json.dumps(s, ensure_ascii=False)}</script>' for s in schemas)}<script src="{root}assets/site.js" defer></script>
</head><body><a class="skip" href="#main">Skip to content</a><header class="site-header">
  <a class="brand" href="{root}index.html"><img src="{root}assets/mark.svg" alt="" width="38" height="38"><span>Garden of Witches <b>Wiki</b></span></a>
  <button class="nav-toggle" aria-expanded="false" aria-controls="site-nav">Menu</button><nav id="site-nav" aria-label="Primary">{nav}</nav></header>
  <main id="main">{breadcrumb_html}{body}</main><footer><div><strong>Garden of Witches Wiki</strong><p>Independent player reference for the 1.0 release. Not affiliated with Team Tapas.</p></div><div><a href="{root}sources.html">Sources &amp; media credits</a><a href="{root}privacy.html">Privacy</a><span>Evidence: {html.escape(source_state)} · updated {UPDATED_DISPLAY}</span></div></footer></body></html>'''
    dest = ROOT / (path or "index.html")
    dest.parent.mkdir(parents=True, exist_ok=True)
    dest.write_text(doc, encoding="utf-8")


